def decode(b, verbose=False):
    """Decode an LZ4 raw block. Returns (output_bytes, list_of_token_descriptions)."""
    out=bytearray(); i=0; toks=[]
    while i < len(b):
        tok=b[i]; start=i; i+=1
        ll=tok>>4; ml=tok&0xf
        if ll==15:
            while True:
                v=b[i]; i+=1; ll+=v
                if v!=255: break
        lits=b[i:i+ll]; i+=ll
        out+=lits
        if i==len(b):
            toks.append("tok=%02x litlen=%d LAST_LITERALS (no match)"%(tok,ll))
            break
        off=b[i]|(b[i+1]<<8); i+=2
        if ml==15:
            while True:
                v=b[i]; i+=1; ml+=v
                if v!=255: break
        mlen=ml+4
        toks.append("tok=%02x litlen=%d off=%d matchlen=%d"%(tok,ll,off,mlen))
        if off==0: raise ValueError("offset 0")
        p=len(out)-off
        if p<0: raise ValueError("offset too far")
        for k in range(mlen):
            out.append(out[p+k])
    return bytes(out),toks
